import{_ as n,C as d,o,c as s,a0 as a,b as r,w as t,a as l,E as c,a1 as u}from"./chunks/framework.DeoJcRVf.js";const A=JSON.parse('{"title":"Sistema Integral de Notificaciones Multicanal (Notifications)","description":"","frontmatter":{},"headers":[],"relativePath":"notifications-ses.md","filePath":"notifications-ses.md"}'),p={name:"notifications-ses.md"};function g(m,e,h,f,E,b){const i=d("Mermaid");return o(),s("div",null,[e[1]||(e[1]=a('<h1 id="sistema-integral-de-notificaciones-multicanal-notifications" tabindex="-1">Sistema Integral de Notificaciones Multicanal (Notifications) <a class="header-anchor" href="#sistema-integral-de-notificaciones-multicanal-notifications" aria-label="Permalink to &quot;Sistema Integral de Notificaciones Multicanal (Notifications)&quot;">​</a></h1><p>El sistema de notificaciones de <strong>Flowex</strong> es un motor distribuido diseñado bajo arquitectura <strong>Event-Driven</strong>. Coordina las comunicaciones hacia remitentes, destinatarios, conductores y personal operativo:</p><ol><li><strong>Amazon Simple Email Service (SES)</strong>: Correos transaccionales en HTML (<code>Flowex-notification-lambda</code>). Es el <strong>único canal de los códigos de verificación</strong> y del segundo factor.</li><li><strong>Meta WhatsApp Business Cloud API</strong>: Avisos del pedido y código de entrega al destinatario, con plantillas aprobadas por Meta (<code>Flowex-otp-service-lambda</code> y <code>Flowex-notification-lambda</code>).</li><li><strong>Bus de Eventos Asíncronos (Amazon SQS)</strong>: Desacoplamiento mediante <code>NotificationsQueue</code> y <code>FlowexConsentQueue</code>.</li><li><strong>Observabilidad (Discord Webhooks)</strong>: Alertas internas de fallos mediante el middleware <code>withSentinel</code>.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Flowex <strong>no envía SMS</strong>. La ruta <code>/notifications/sms/verify-phone</code> y el canal SMS del segundo factor se eliminaron: solo escribían en el log y respondían «enviado».</p></div><hr><h2 id="🏗️-arquitectura-global-del-flujo-de-notificaciones" tabindex="-1">🏗️ Arquitectura Global del Flujo de Notificaciones <a class="header-anchor" href="#🏗️-arquitectura-global-del-flujo-de-notificaciones" aria-label="Permalink to &quot;🏗️ Arquitectura Global del Flujo de Notificaciones&quot;">​</a></h2>',6)),(o(),r(u,null,{default:t(()=>[c(i,{id:"mermaid-37",class:"mermaid",graph:"graph%20TB%0A%20%20%20%20subgraph%20Or%C3%ADgenes%20de%20Eventos%0A%20%20%20%20%20%20%20%20Auth%5BFlowex-auth-api-lambda%3Cbr%3ELogin%20%2F%202FA%20MFA%5D%0A%20%20%20%20%20%20%20%20Orders%5BFlowex-auth-admin-lambda%3Cbr%3ECreaci%C3%B3n%2C%20En%20Reparto%2C%20POD%2C%20Retenci%C3%B3n%5D%0A%20%20%20%20%20%20%20%20RegPublic%5BFlowex-registration-public-lambda%3Cbr%3EOnboarding%20de%20Clientes%5D%0A%20%20%20%20%20%20%20%20RegAdmin%5BFlowex-registration-admin-lambda%3Cbr%3EAprobaci%C3%B3n%20de%20Conductores%5D%0A%20%20%20%20%20%20%20%20Frontend%5BFlowex%20Frontend%20SPA%3Cbr%3EConfirmaci%C3%B3n%20de%20Pago%20y%20Seguimiento%5D%0A%20%20%20%20%20%20%20%20Consent%5BFlowex-consent-worker-lambda%3Cbr%3EDerechos%20ARCO%20Ley%2021.719%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Encolamiento%20y%20Desacoplamiento%0A%20%20%20%20%20%20%20%20SQSNotif%5B%5BAmazon%20SQS%3A%20NotificationsQueue%5D%5D%0A%20%20%20%20%20%20%20%20SQSConsent%5B%5BAmazon%20SQS%3A%20FlowexConsentQueue%5D%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Microservicios%20de%20Notificaci%C3%B3n%0A%20%20%20%20%20%20%20%20OTPService%5BFlowex-otp-service-lambda%3Cbr%3EC%C3%B3digo%20por%20correo%20%26%20avisos%20WhatsApp%5D%0A%20%20%20%20%20%20%20%20NotifWorker%5BFlowex-notification-lambda%3Cbr%3EProcesador%20SQS%20%26%20Amazon%20SES%20Engine%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Canales%20de%20Salida%0A%20%20%20%20%20%20%20%20MetaCloud%5BMeta%20WhatsApp%20Cloud%20API%3Cbr%3EGraph%20API%20v19.0%5D%0A%20%20%20%20%20%20%20%20AmazonSES%5BAmazon%20SES%3Cbr%3EHTML%20Emails%20Transaccionales%5D%0A%20%20%20%20%20%20%20%20DiscordWebhook%5BDiscord%20Webhook%3Cbr%3EAlertas%20Sentinel%20de%20Monitoreo%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Auth%20--%3E%7CSQS%20AUTH_MFA_OTP%7C%20SQSNotif%0A%20%20%20%20Orders%20--%3E%7CSQS%20ORDER_CREATED%20%2F%20STATUS%20%2F%20DISCREPANCY%7C%20SQSNotif%0A%20%20%20%20RegPublic%20--%3E%7CPOST%20%2Fotp%2Fsend%7C%20OTPService%0A%20%20%20%20RegAdmin%20--%3E%7CSQS%20USER_REGISTRATION_ACTIVATED%7C%20SQSNotif%0A%20%20%20%20Frontend%20--%3E%7CPOST%20%2Fnotifications%2Fwhatsapp%7C%20OTPService%0A%20%20%20%20Consent%20--%3E%7CSQS%20CONTACT_ERASURE_NOTICE%7C%20SQSNotif%0A%0A%20%20%20%20OTPService%20--%3E%7CAvisos%20de%20pedido%7C%20MetaCloud%0A%20%20%20%20OTPService%20--%3E%7CCLIENT_REG_OTP%20c%C3%B3digo%20por%20correo%7C%20SQSNotif%0A%0A%20%20%20%20SQSNotif%20--%3E%7CBatch%20Processing%7C%20NotifWorker%0A%20%20%20%20NotifWorker%20--%3E%7CSendEmailCommand%7C%20AmazonSES%0A%20%20%20%20NotifWorker%20--%3E%7CPlantillas%20de%20pedido%7C%20MetaCloud%0A%20%20%20%20NotifWorker%20--%3E%7CreportErrorToDiscord%7C%20DiscordWebhook%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="📋-catalogo-completo-de-notificaciones-por-canal" tabindex="-1">📋 Catálogo Completo de Notificaciones por Canal <a class="header-anchor" href="#📋-catalogo-completo-de-notificaciones-por-canal" aria-label="Permalink to &quot;📋 Catálogo Completo de Notificaciones por Canal&quot;">​</a></h2><h3 id="_1-canal-meta-whatsapp-business-cloud-api-flowex-otp-service-lambda" tabindex="-1">1. Canal Meta WhatsApp Business Cloud API (<code>Flowex-otp-service-lambda</code>) <a class="header-anchor" href="#_1-canal-meta-whatsapp-business-cloud-api-flowex-otp-service-lambda" aria-label="Permalink to &quot;1. Canal Meta WhatsApp Business Cloud API (`Flowex-otp-service-lambda`)&quot;">​</a></h3><p>Todas las plantillas de WhatsApp están tipadas en [<code>whatsapp-templates.ts</code>](file:///C:/Users/joyta/OneDrive/Desktop/inspytech/flowEx/Flowex-otp-service-lambda/src/whatsapp-templates.ts) y aprobadas por Meta:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Evento del Sistema</th><th style="text-align:left;">Plantilla Oficial Meta</th><th style="text-align:left;">Categoría</th><th style="text-align:left;">Variables Dinámicas</th><th style="text-align:left;">Destinatario Principal</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Envío Creado y Pagado</strong></td><td style="text-align:left;"><code>flowex_order_created_v2</code></td><td style="text-align:left;"><code>UTILITY</code> (con Header de Imagen)</td><td style="text-align:left;"><code>1</code> Tracking, <code>2</code> PIN de entrega (4 dígitos), <code>3</code> Nombre Destinatario, <code>4</code> Comuna, <code>5</code> Dirección, <code>6</code> Nombre Remitente</td><td style="text-align:left;">Destinatario del Paquete</td></tr><tr><td style="text-align:left;"><strong>Paquete en Salida Hoy</strong></td><td style="text-align:left;"><code>flowex_order_out_today</code></td><td style="text-align:left;"><code>UTILITY</code></td><td style="text-align:left;"><code>1</code> Tracking, <code>2</code> Nombre Chofer, <code>3</code> Destinatario, <code>4</code> PIN de Entrega</td><td style="text-align:left;">Destinatario del Paquete</td></tr><tr><td style="text-align:left;"><strong>Alerta de Parada Próxima</strong></td><td style="text-align:left;"><code>flowex_order_next_stop</code></td><td style="text-align:left;"><code>UTILITY</code></td><td style="text-align:left;"><code>1</code> Tracking, <code>2</code> Nombre Chofer, <code>3</code> Destinatario, <code>4</code> PIN, <code>5</code> Dirección de Entrega</td><td style="text-align:left;">Destinatario del Paquete</td></tr><tr><td style="text-align:left;"><strong>Actualización en Tránsito</strong></td><td style="text-align:left;"><code>flowex_order_in_transit</code></td><td style="text-align:left;"><code>UTILITY</code></td><td style="text-align:left;"><code>1</code> Tracking, <code>2</code> Estado / hub donde está el pedido, <code>3</code> Destinatario</td><td style="text-align:left;">Remitente y Destinatario</td></tr><tr><td style="text-align:left;"><strong>Confirmación de Entrega (POD)</strong></td><td style="text-align:left;"><code>flowex_order_delivered</code></td><td style="text-align:left;"><code>UTILITY</code></td><td style="text-align:left;"><code>1</code> Tracking, <code>2</code> Fecha y Hora de Entrega, <code>3</code> Nombre Destinatario</td><td style="text-align:left;">Remitente y Destinatario</td></tr><tr><td style="text-align:left;"><strong>Incidencia / Fallo de Entrega</strong></td><td style="text-align:left;"><code>flowex_delivery_incident</code></td><td style="text-align:left;"><code>UTILITY</code></td><td style="text-align:left;"><code>1</code> Tracking, <code>2</code> Motivo del Fallo, <code>3</code> Destinatario</td><td style="text-align:left;">Destinatario y Remitente</td></tr><tr><td style="text-align:left;"><strong>Notificación de Contingencia</strong></td><td style="text-align:left;"><code>flowex_general_notification</code></td><td style="text-align:left;"><code>UTILITY</code> (Fallback)</td><td style="text-align:left;"><code>1</code> Texto del aviso general</td><td style="text-align:left;">Usuarios de la plataforma</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Sin credenciales de Meta no sale nada.</strong> El envío responde <code>status: &quot;not_sent&quot;</code> y <code>delivered: false</code>, y no se registra como uso del teléfono del destinatario. Antes se simulaba (<code>mock_sent</code>), se contaba como entregado y quedaba auditado un envío que no ocurrió.</p></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Seguridad del PIN de Entrega:</strong> El PIN de 4 dígitos generado aleatoriamente con <code>crypto.randomInt</code> viaja exclusivamente en las plantillas directas al destinatario (<code>flowex_order_created_v2</code>, <code>flowex_order_out_today</code>, <code>flowex_order_next_stop</code>). Los conductores <strong>no</strong> tienen acceso visual al PIN en su interfaz móvil y solo pueden registrar la entrega cuando el receptor se lo proporciona verbalmente.</p></div><hr><h3 id="_2-canal-amazon-ses-correos-electronicos-html-flowex-notification-lambda" tabindex="-1">2. Canal Amazon SES - Correos Electrónicos HTML (<code>Flowex-notification-lambda</code>) <a class="header-anchor" href="#_2-canal-amazon-ses-correos-electronicos-html-flowex-notification-lambda" aria-label="Permalink to &quot;2. Canal Amazon SES - Correos Electrónicos HTML (`Flowex-notification-lambda`)&quot;">​</a></h3><p>Los correos emitidos por Amazon SES utilizan plantillas HTML con la identidad corporativa de Flowex, tipografía legible y diseño adaptativo:</p><h4 id="a-verificacion-de-cuenta-notifications-email-verify-account-o-evento-client-reg-otp" tabindex="-1">A. Verificación de Cuenta (<code>/notifications/email/verify-account</code> o evento <code>CLIENT_REG_OTP</code>) <a class="header-anchor" href="#a-verificacion-de-cuenta-notifications-email-verify-account-o-evento-client-reg-otp" aria-label="Permalink to &quot;A. Verificación de Cuenta (`/notifications/email/verify-account` o evento `CLIENT_REG_OTP`)&quot;">​</a></h4><ul><li><strong>Asunto:</strong> <code>Flowex: Código para Validación de Cuenta</code></li><li><strong>Destinatario:</strong> Usuario en proceso de registro de cuenta.</li><li><strong>Contenido:</strong> Contenedor destacado con el código OTP de 6 dígitos con espaciado amplio (<code>letter-spacing: 4px</code>) y advertencia de no compartirlo.</li></ul><h4 id="b-segundo-factor-de-autenticacion-2fa-auth-mfa-otp" tabindex="-1">B. Segundo Factor de Autenticación 2FA (<code>AUTH_MFA_OTP</code>) <a class="header-anchor" href="#b-segundo-factor-de-autenticacion-2fa-auth-mfa-otp" aria-label="Permalink to &quot;B. Segundo Factor de Autenticación 2FA (`AUTH_MFA_OTP`)&quot;">​</a></h4><ul><li><strong>Asunto:</strong> <code>Flowex: Código de Verificación de Inicio de Sesión</code></li><li><strong>Destinatario:</strong> Usuarios autenticados con roles protegidos (<code>root</code>, <code>admin</code>, <code>driver</code>).</li><li><strong>Contenido:</strong> Código de 6 dígitos numéricos con vencimiento estricto a los 5 minutos, rol específico y leyenda de cumplimiento de la <strong>Ley N° 21.719 de Chile</strong>.</li></ul><h4 id="c-bienvenida-y-activacion-de-cuenta-notifications-email-welcome-o-evento-user-registration-activated" tabindex="-1">C. Bienvenida y Activación de Cuenta (<code>/notifications/email/welcome</code> o evento <code>USER_REGISTRATION_ACTIVATED</code>) <a class="header-anchor" href="#c-bienvenida-y-activacion-de-cuenta-notifications-email-welcome-o-evento-user-registration-activated" aria-label="Permalink to &quot;C. Bienvenida y Activación de Cuenta (`/notifications/email/welcome` o evento `USER_REGISTRATION_ACTIVATED`)&quot;">​</a></h4><ul><li><strong>Asunto:</strong> <code>Flowex: ¡Bienvenido a nuestra plataforma!</code> o <code>Flowex: ¡Tu Cuenta ha sido Activada!</code></li><li><strong>Destinatario:</strong> Cliente o Conductor tras la aprobación de su cuenta.</li><li><strong>Contenido:</strong> Saludo cordial, confirmación del rol asignado y botón de llamado a la acción hacia <code>https://flowex.cl/login</code>.</li></ul><h4 id="d-confirmacion-de-despacho-y-comprobante-oficial-notifications-email-order-created-o-evento-order-created" tabindex="-1">D. Confirmación de Despacho y Comprobante Oficial (<code>/notifications/email/order-created</code> o evento <code>ORDER_CREATED</code>) <a class="header-anchor" href="#d-confirmacion-de-despacho-y-comprobante-oficial-notifications-email-order-created-o-evento-order-created" aria-label="Permalink to &quot;D. Confirmación de Despacho y Comprobante Oficial (`/notifications/email/order-created` o evento `ORDER_CREATED`)&quot;">​</a></h4><ul><li><strong>Asunto:</strong> <code>Flowex: Confirmación de Pedido {trackingNumber}</code></li><li><strong>Destinatario:</strong> Remitente y/o pagador del envío.</li><li><strong>Contenido:</strong> Número de seguimiento oficial <code>FLX-YYYY-XXXX</code>, PIN de seguridad de 4 dígitos, monto total pagado en CLP y botón con enlace directo a rastreo en vivo (<code>/tracking?code=FLX-...</code>).</li></ul><h4 id="e-entrega-fallida-notifications-email-order-status-update-o-evento-order-status-update" tabindex="-1">E. Entrega fallida (<code>/notifications/email/order-status-update</code> o evento <code>ORDER_STATUS_UPDATE</code>) <a class="header-anchor" href="#e-entrega-fallida-notifications-email-order-status-update-o-evento-order-status-update" aria-label="Permalink to &quot;E. Entrega fallida (`/notifications/email/order-status-update` o evento `ORDER_STATUS_UPDATE`)&quot;">​</a></h4><ul><li><strong>Asunto:</strong> <code>Flowex: Estado de tu pedido {trackingNumber} en {ESTADO}</code></li><li><strong>Destinatario:</strong> El <strong>remitente</strong>, solo cuando el estado es <code>delivery_failed</code> (matriz aprobada el 16-09-2026). Los demás estados no envían correo; la salida a reparto se avisa al destinatario por WhatsApp.</li><li><strong>Contenido:</strong> Estado, observaciones y enlace al rastreo público, que muestra el nombre del hub donde está el pedido.</li></ul><h4 id="f-retencion-por-discrepancia-de-bultos-notifications-email-package-discrepancy-o-evento-order-package-discrepancy" tabindex="-1">F. Retención por Discrepancia de Bultos (<code>/notifications/email/package-discrepancy</code> o evento <code>ORDER_PACKAGE_DISCREPANCY</code>) <a class="header-anchor" href="#f-retencion-por-discrepancia-de-bultos-notifications-email-package-discrepancy-o-evento-order-package-discrepancy" aria-label="Permalink to &quot;F. Retención por Discrepancia de Bultos (`/notifications/email/package-discrepancy` o evento `ORDER_PACKAGE_DISCREPANCY`)&quot;">​</a></h4><ul><li><strong>Asunto:</strong> <code>Flowex: tu pedido {trackingNumber} requiere pagar una diferencia para ser entregado</code></li><li><strong>Destinatario:</strong> Cliente remitente.</li><li><strong>Contenido:</strong> Cuadro comparativo con la categoría de bulto declarada vs. la categoría verificada en la báscula del hub, el monto de la diferencia tarifaria en CLP, las observaciones del operador de bodega y la explicación de que el paquete queda retenido sin costo para el destinatario hasta que el remitente regularice el pago.</li></ul><h4 id="g-solicitud-de-supresion-de-contacto-de-libreta-contact-erasure-notice-ley-n°-21-719" tabindex="-1">G. Solicitud de Supresión de Contacto de Libreta (<code>CONTACT_ERASURE_NOTICE</code> - Ley N° 21.719) <a class="header-anchor" href="#g-solicitud-de-supresion-de-contacto-de-libreta-contact-erasure-notice-ley-n°-21-719" aria-label="Permalink to &quot;G. Solicitud de Supresión de Contacto de Libreta (`CONTACT_ERASURE_NOTICE` - Ley N° 21.719)&quot;">​</a></h4><ul><li><strong>Asunto:</strong> <code>Flowex: solicitud de supresión de un contacto de tu libreta ({ticket})</code></li><li><strong>Destinatario:</strong> Remitente titular de una libreta de direcciones.</li><li><strong>Contenido:</strong> Aviso formal de que un tercero ha ejercido su derecho de supresión sobre su número de teléfono (enmascarado <code>+56 9 **** 1234</code>), otorgándole <strong>10 días corridos</strong> para acreditar una base de licitud contractual antes de la purga definitiva del registro de la libreta.</li></ul><hr><h3 id="_3-canal-de-alertas-operativas-y-de-monitoreo-discord-webhooks" tabindex="-1">3. Canal de Alertas Operativas y de Monitoreo (Discord Webhooks) <a class="header-anchor" href="#_3-canal-de-alertas-operativas-y-de-monitoreo-discord-webhooks" aria-label="Permalink to &quot;3. Canal de Alertas Operativas y de Monitoreo (Discord Webhooks)&quot;">​</a></h3><p>A través del middleware transversal <code>withSentinel</code> (<code>reportErrorToDiscord</code>):</p><ul><li><strong>Fallo en Procesamiento de Cola SQS:</strong> Alerta con <code>MessageId</code>, stack trace del error y carga útil del evento si falla la entrega tras reintentos en <code>Flowex-notification-lambda</code>.</li><li><strong>Excepciones 500 no controladas:</strong> Envío inmediato a canales privados de ingeniería (<code>#flowex-alerts</code>) con detalles del endpoint HTTP y contexto de ejecución.</li><li><strong>Notificaciones de Discrepancia Crítica:</strong> Aviso cuando una preferencia de Mercado Pago o sesión de Fintoc no cuadra con el monto registrado en base de datos.</li></ul><hr><h2 id="⚙️-control-de-preferencias-del-usuario-opt-in-opt-out" tabindex="-1">⚙️ Control de Preferencias del Usuario (Opt-in / Opt-out) <a class="header-anchor" href="#⚙️-control-de-preferencias-del-usuario-opt-in-opt-out" aria-label="Permalink to &quot;⚙️ Control de Preferencias del Usuario (Opt-in / Opt-out)&quot;">​</a></h2><p>En conformidad con los estándares de privacidad y la <strong>Ley N° 21.719</strong>, cada perfil de usuario en Flowex dispone de un objeto configurable de preferencias de comunicación (<code>NotificationPreferences</code>):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;emailSes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;whatsappMeta&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Una preferencia <code>smsSns</code> guardada antes se ignora.</p><ul><li><strong>Actualización:</strong> Mediante <code>PUT /users/me/notifications</code>.</li><li><strong>Revocación:</strong> Si el usuario desmarca un canal, el sistema omite el despacho de comunicaciones no esenciales a través de dicho medio, manteniendo únicamente aquellas estrictamente requeridas para la ejecución contractual del servicio de transporte.</li></ul><hr><h2 id="🧪-ambiente-de-desarrollo-y-desvio-seguro-dev-redirect-email" tabindex="-1">🧪 Ambiente de Desarrollo y Desvío Seguro (<code>DEV_REDIRECT_EMAIL</code>) <a class="header-anchor" href="#🧪-ambiente-de-desarrollo-y-desvio-seguro-dev-redirect-email" aria-label="Permalink to &quot;🧪 Ambiente de Desarrollo y Desvío Seguro (`DEV_REDIRECT_EMAIL`)&quot;">​</a></h2><p>Para evitar el envío accidental de correos o mensajes a destinatarios reales durante pruebas de desarrollo y control de calidad (QA):</p><ul><li><strong>Variable <code>DEV_REDIRECT_EMAIL</code></strong>: Si está configurada en la función Lambda, todos los correos electrónicos se envían exclusivamente al buzón de pruebas indicado.</li><li><strong>Banner de Advertencia:</strong> El encabezado del correo se decora automáticamente con un banner amarillo:<div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;background:#fef3c7; border:1px solid #f59e0b; padding:12px; color:#78350f;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  CORREO DE DESARROLLO — NO ES UN ENVÍO REAL&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">br</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Destinatario que corresponde en producción: destinatario.real@ejemplo.cl</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div></li><li><strong>Sin SES configurado (<code>NODE_ENV=development</code> sin <code>DEV_REDIRECT_EMAIL</code>):</strong> el correo no sale; queda solo el registro en el log y no se audita como uso de datos.</li></ul>',38))])}const v=n(p,[["render",g]]);export{A as __pageData,v as default};
